import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Building2, MapPin, Globe, Mail, Phone, User, Users, Briefcase, Plus, Edit2, CheckCircle2, Clock, X, ChevronRight, ExternalLink } from 'lucide-react';
import { EmployerService } from '../../domain/employerService';

const EmployerProfile = () => {
  const { id } = useParams();
  const [employer, setEmployer] = useState(null);
  const [jobs, setJobs] = useState([]);
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showJobModal, setShowJobModal] = useState(false);
  const [formData, setFormData] = useState({});
  const [jobFormData, setJobFormData] = useState({
    title: '',
    location: '',
    jobType: 'Full-time',
    experience: '',
    salary: '',
    description: '',
    requirements: '',
    skills: '',
    applicationDeadline: '',
    eligibilityCriteria: {
      minCGPA: 7.0,
      departments: [],
      year: 4
    }
  });
  const [message, setMessage] = useState('');
  const [formLoading, setFormLoading] = useState(false);

  useEffect(() => {
    loadEmployerProfile();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const loadEmployerProfile = async () => {
    try {
      setLoading(true);
      const [employerData, jobsData, applicationsData] = await Promise.all([
        EmployerService.getEmployerById(id),
        EmployerService.getEmployerJobs(id),
        EmployerService.getEmployerApplications(id)
      ]);

      setEmployer(employerData);
      setJobs(jobsData);
      setApplications(applicationsData);
      setFormData(employerData || {});
    } catch (error) {
      console.error('Failed to load employer profile:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleEditProfile = () => {
    setFormData(employer);
    setMessage('');
    setShowEditModal(true);
  };

  const handleAddJob = () => {
    setJobFormData({
      title: '',
      location: '',
      jobType: 'Full-time',
      experience: '',
      salary: '',
      description: '',
      requirements: '',
      skills: '',
      applicationDeadline: '',
      eligibilityCriteria: {
        minCGPA: 7.0,
        departments: [],
        year: 4
      }
    });
    setMessage('');
    setShowJobModal(true);
  };

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleJobInputChange = (e) => {
    if (e.target.name.startsWith('eligibility.')) {
      const field = e.target.name.split('.')[1];
      setJobFormData({
        ...jobFormData,
        eligibilityCriteria: {
          ...jobFormData.eligibilityCriteria,
          [field]: e.target.type === 'number' ? parseFloat(e.target.value) : e.target.value
        }
      });
    } else {
      setJobFormData({
        ...jobFormData,
        [e.target.name]: e.target.value
      });
    }
  };

  const handleDepartmentChange = (e) => {
    const value = e.target.value;
    const departments = jobFormData.eligibilityCriteria.departments;

    if (e.target.checked) {
      setJobFormData({
        ...jobFormData,
        eligibilityCriteria: {
          ...jobFormData.eligibilityCriteria,
          departments: [...departments, value]
        }
      });
    } else {
      setJobFormData({
        ...jobFormData,
        eligibilityCriteria: {
          ...jobFormData.eligibilityCriteria,
          departments: departments.filter(dept => dept !== value)
        }
      });
    }
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setMessage('');

    try {
      await EmployerService.updateEmployerProfile(id, formData);
      setMessage('Profile updated successfully!');

      setTimeout(() => {
        setShowEditModal(false);
        loadEmployerProfile();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setFormLoading(false);
    }
  };

  const handleJobSubmit = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setMessage('');

    try {
      const jobData = {
        ...jobFormData,
        requirements: jobFormData.requirements.split('\n').filter(req => req.trim()),
        skills: jobFormData.skills.split(',').map(skill => skill.trim()).filter(skill => skill)
      };

      await EmployerService.postJob(id, jobData);
      setMessage('Job posted successfully!');

      setTimeout(() => {
        setShowJobModal(false);
        loadEmployerProfile();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setFormLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'under_review': 'bg-gold-500/10 text-gold-500 border-gold-500/20',
      'shortlisted': 'bg-blue-500/10 text-blue-400 border-blue-500/20',
      'accepted': 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
      'rejected': 'bg-rose-500/10 text-rose-400 border-rose-500/20',
      'active': 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
      'inactive': 'bg-pearl-800/10 text-pearl-600 border-pearl-800/20'
    };

    const classes = statusConfig[status] || 'bg-pearl-800/10 text-pearl-600 border-pearl-800/20';
    return (
      <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold border tracking-widest uppercase ${classes}`}>
        {status.replace('_', ' ')}
      </span>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-gold-500/20 border-t-gold-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!employer) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center p-6">
        <div className="glass text-rose-400 px-8 py-5 rounded-2xl border border-rose-500/20 font-medium">
          Employer not found.
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-onyx-900 pb-24 font-sans text-pearl-200">
      {/* Header Area with Premium Onyx & Gold */}
      <div className="h-80 bg-onyx-950 relative overflow-hidden">
        <div className="absolute inset-0 bg-gold-gradient opacity-[0.03]"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[1000px] bg-gold-500/5 rounded-full blur-[150px]"></div>
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-5"></div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-40 relative z-10">

        {/* Top Profile Card - Glassmorphism */}
        <div className="glass rounded-[2.5rem] p-8 md:p-12 mb-10 border border-pearl-900/10 shadow-2xl flex flex-col md:flex-row gap-10 items-center md:items-start">
          <div className="w-40 h-40 md:w-52 md:h-52 rounded-3xl bg-onyx-800 p-4 shadow-2xl shrink-0 border border-pearl-900/10 overflow-hidden relative group">
            <img 
              src={employer.logo || 'https://via.placeholder.com/200x200?text=Company'} 
              alt="Company Logo" 
              className="w-full h-full object-contain rounded-2xl grayscale group-hover:grayscale-0 transition-all duration-500"
            />
            <div className="absolute inset-0 bg-gold-gradient opacity-0 group-hover:opacity-10 transition-opacity"></div>
          </div>

          <div className="flex-1 w-full text-center md:text-left">
            <div className="flex flex-col md:flex-row md:justify-between md:items-start gap-6">
              <div>
                <div className="flex flex-col md:flex-row items-center md:items-center gap-4 mb-4">
                  <h1 className="text-4xl md:text-6xl font-serif font-bold text-white tracking-tight leading-none">{employer.companyName}</h1>
                  {employer.isVerified ? (
                    <div className="flex items-center gap-2 bg-emerald-500/10 text-emerald-400 px-3 py-1 rounded-full text-xs font-bold border border-emerald-500/20 uppercase tracking-widest">
                      <CheckCircle2 size={14} /> Verified
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 bg-gold-500/10 text-gold-500 px-3 py-1 rounded-full text-xs font-bold border border-gold-500/20 uppercase tracking-widest">
                      <Clock size={14} /> Pending
                    </div>
                  )}
                </div>
                <p className="text-xl text-pearl-400 font-light mb-6 flex items-center justify-center md:justify-start gap-3">
                  <Building2 size={24} className="text-gold-500"/> {employer.industry}
                </p>

                <div className="flex flex-wrap justify-center md:justify-start gap-4">
                  <span className="px-4 py-2 bg-onyx-800/50 text-pearl-500 rounded-xl text-sm font-medium border border-pearl-900/10 flex items-center gap-2">
                    <Users size={18} className="text-gold-500/50"/> {employer.companySize || '50-200'} Employees
                  </span>
                  <span className="px-4 py-2 bg-onyx-800/50 text-pearl-500 rounded-xl text-sm font-medium border border-pearl-900/10 flex items-center gap-2">
                    <Briefcase size={18} className="text-gold-500/50"/> {jobs.length} Active Positions
                  </span>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto shrink-0 pt-4 md:pt-0">
                <button onClick={handleEditProfile} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-3.5 glass text-white font-bold rounded-2xl hover:bg-white/5 transition-all border border-pearl-900/20">
                  <Edit2 size={18} /> Edit Profile
                </button>
                {employer.isVerified && (
                  <button onClick={handleAddJob} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-3.5 bg-gold-gradient text-onyx-900 font-bold rounded-2xl hover:brightness-110 transition-all shadow-gold">
                    <Plus size={18} /> Post Listing
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

          {/* Left Column */}
          <div className="space-y-10">

            {/* About */}
            <div className="glass rounded-[2rem] border border-pearl-900/10 p-10">
              <h3 className="text-2xl font-serif font-bold text-white mb-6 flex items-center gap-3">
                <div className="w-1.5 h-6 bg-gold-500 rounded-full"></div>
                Philosophy
              </h3>
              <p className="text-pearl-400 leading-relaxed font-light text-lg">
                {employer.description || 'Our vision is to redefine industry standards through innovation and excellence. We are constantly seeking elite talent to join our global mission.'}
              </p>
            </div>

            {/* Contact */}
            <div className="glass rounded-[2rem] border border-pearl-900/10 p-10">
              <h3 className="text-2xl font-serif font-bold text-white mb-8">Global Access</h3>
              <ul className="space-y-8">
                <li className="flex items-start gap-5 group">
                  <div className="w-12 h-12 rounded-2xl bg-onyx-800 text-gold-500 flex items-center justify-center shrink-0 group-hover:bg-gold-500 group-hover:text-onyx-900 transition-all border border-pearl-900/10">
                    <Globe size={22} />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-pearl-700 uppercase tracking-widest mb-1">Official Domain</p>
                    <a href={employer.website} target="_blank" rel="noopener noreferrer" className="text-pearl-200 font-bold hover:text-gold-500 transition-colors flex items-center gap-2">
                      {employer.website || 'N/A'} <ExternalLink size={14} />
                    </a>
                  </div>
                </li>
                <li className="flex items-start gap-5 group">
                  <div className="w-12 h-12 rounded-2xl bg-onyx-800 text-gold-500 flex items-center justify-center shrink-0 group-hover:bg-gold-500 group-hover:text-onyx-900 transition-all border border-pearl-900/10">
                    <Mail size={22} />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-pearl-700 uppercase tracking-widest mb-1">Corporate Email</p>
                    <a href={`mailto:${employer.email}`} className="text-pearl-200 font-bold hover:text-gold-500 transition-colors">
                      {employer.email}
                    </a>
                  </div>
                </li>
                <li className="flex items-start gap-5 group">
                  <div className="w-12 h-12 rounded-2xl bg-onyx-800 text-gold-500 flex items-center justify-center shrink-0 group-hover:bg-gold-500 group-hover:text-onyx-900 transition-all border border-pearl-900/10">
                    <MapPin size={22} />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-pearl-700 uppercase tracking-widest mb-1">Headquarters</p>
                    <p className="text-pearl-200 font-bold leading-tight">
                      {employer.address || 'Global Operations'}
                    </p>
                  </div>
                </li>
              </ul>
            </div>

            {/* Key Contact */}
            <div className="glass rounded-[2rem] border border-pearl-900/10 p-10 bg-onyx-gradient">
              <h3 className="text-2xl font-serif font-bold text-white mb-8">Talent Acquisition</h3>
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 rounded-2xl bg-gold-gradient text-onyx-900 flex items-center justify-center shrink-0 text-2xl font-black shadow-gold">
                  {(employer.contactPerson || 'A').charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="text-xl font-bold text-white">{employer.contactPerson || 'Admissions Lead'}</p>
                  <p className="text-gold-500 text-sm font-bold uppercase tracking-tighter">{employer.contactDesignation || 'Global Recruitment'}</p>
                </div>
              </div>
            </div>

          </div>

          {/* Right Column */}
          <div className="lg:col-span-2 space-y-10">

            {/* Active Listings */}
            <div className="glass rounded-[2.5rem] border border-pearl-900/10 overflow-hidden shadow-xl">
              <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold text-white">Elite Opportunities</h3>
                  <p className="text-pearl-500 text-sm mt-1 font-light tracking-wide">Current openings for exceptional candidates.</p>
                </div>
                <div className="w-12 h-12 rounded-2xl bg-onyx-800 flex items-center justify-center text-gold-500 font-bold border border-pearl-900/10">
                  {jobs.length}
                </div>
              </div>

              <div className="p-0">
                {jobs.length > 0 ? (
                  <div className="divide-y divide-pearl-900/5">
                    {jobs.map(job => (
                      <div key={job.id} className="p-10 hover:bg-white/[0.02] transition-all group flex flex-col md:flex-row md:items-center justify-between gap-10">
                        <div className="flex-1">
                          <Link to={`/job/${job.id}`} className="text-2xl font-serif font-bold text-white hover:text-gold-400 transition-colors mb-4 inline-block tracking-tight">
                            {job.title}
                          </Link>
                          <div className="flex flex-wrap items-center gap-5 text-sm text-pearl-500 font-light mb-6">
                            <span className="flex items-center gap-2"><MapPin size={18} className="text-gold-500/50"/> {job.location}</span>
                            <span className="w-1 h-1 bg-pearl-800 rounded-full"></span>
                            <span className="flex items-center gap-2"><Briefcase size={18} className="text-gold-500/50"/> {job.jobType}</span>
                            <span className="w-1 h-1 bg-pearl-800 rounded-full"></span>
                            <span className="text-pearl-700">{new Date(job.postedDate).toLocaleDateString()}</span>
                          </div>
                          <div className="flex items-center gap-6">
                            {getStatusBadge(job.status)}
                            <span className="text-xs font-bold text-pearl-600 flex items-center gap-2 uppercase tracking-widest">
                              <Users size={16} className="text-gold-500/30"/> {job.applicationsReceived} Applications
                            </span>
                          </div>
                        </div>
                        <Link to={`/job/${job.id}`} className="shrink-0 w-14 h-14 rounded-2xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 group-hover:border-gold-500 group-hover:text-gold-500 transition-all">
                          <ChevronRight size={24} />
                        </Link>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="p-20 text-center">
                    <div className="w-20 h-20 bg-onyx-800 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-pearl-900/10">
                      <Briefcase className="text-gold-500/30" size={32} />
                    </div>
                    <h4 className="text-2xl font-serif font-bold text-white mb-4">No active listings</h4>
                    <p className="text-pearl-500 mb-10 max-w-sm mx-auto font-light">Begin your recruitment journey by announcing your first elite position.</p>
                    {employer.isVerified && (
                      <button onClick={handleAddJob} className="bg-gold-gradient text-onyx-900 px-10 py-4 rounded-2xl font-bold hover:brightness-110 transition-all shadow-gold inline-flex items-center gap-3">
                        <Plus size={20} /> Create Listing
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Talent Pipeline Table */}
            <div className="glass rounded-[2.5rem] border border-pearl-900/10 overflow-hidden shadow-xl">
              <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
                <div>
                  <h3 className="text-2xl font-serif font-bold text-white">Talent Pipeline</h3>
                  <p className="text-pearl-500 text-sm mt-1 font-light tracking-wide">Inbound application management.</p>
                </div>
              </div>

              <div className="p-0">
                {applications.length > 0 ? (
                  <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead>
                        <tr className="bg-onyx-950/50 text-pearl-700 text-[10px] uppercase tracking-[0.2em] font-black">
                          <th className="py-6 px-10">Candidate</th>
                          <th className="py-6 px-10">Role</th>
                          <th className="py-6 px-10">Status</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-pearl-900/5">
                        {applications.slice(0, 10).map(application => (
                          <tr key={application.id} className="hover:bg-white/[0.02] transition-colors">
                            <td className="py-6 px-10">
                              <div className="flex items-center gap-4">
                                <div className="w-10 h-10 rounded-xl bg-onyx-800 text-gold-500 flex items-center justify-center font-black text-sm shrink-0 border border-pearl-900/10">
                                  {application.studentName.charAt(0).toUpperCase()}
                                </div>
                                <span className="font-bold text-white tracking-tight">{application.studentName}</span>
                              </div>
                            </td>
                            <td className="py-6 px-10 font-light text-pearl-400">{application.jobTitle}</td>
                            <td className="py-6 px-10">{getStatusBadge(application.status)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="p-20 text-center">
                    <div className="w-20 h-20 bg-onyx-800 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-pearl-900/10">
                      <User className="text-gold-500/30" size={32} />
                    </div>
                    <p className="text-pearl-600 font-light italic">Waiting for exceptional candidates to apply.</p>
                  </div>
                )}
              </div>
            </div>

          </div>
        </div>
      </div>

      {/* Modals - Dark & Elegant */}

      {/* Edit Profile Modal */}
      {showEditModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-onyx-950/80 backdrop-blur-md overflow-y-auto">
          <div className="glass rounded-[3rem] w-full max-w-3xl shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-pearl-900/10 overflow-hidden my-auto animate-fade-in-up">
            <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
              <h3 className="text-2xl font-serif font-bold text-white">Refine Corporate Profile</h3>
              <button onClick={() => setShowEditModal(false)} className="text-pearl-600 hover:text-white bg-onyx-800 p-2.5 rounded-xl transition-all border border-pearl-900/10">
                <X size={20} />
              </button>
            </div>

            <div className="p-10 max-h-[70vh] overflow-y-auto custom-scrollbar">
              {message && (
                <div className={`p-5 rounded-2xl mb-8 font-bold text-sm uppercase tracking-widest flex items-start gap-4 ${message.includes('successfully') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0" /> : <X size={20} className="shrink-0" />}
                  <p>{message}</p>
                </div>
              )}

              <form onSubmit={handleProfileSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Company Identity</label>
                    <input type="text" name="companyName" value={formData.companyName || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white placeholder-pearl-800" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Industry Vertical</label>
                    <input type="text" name="industry" value={formData.industry || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white placeholder-pearl-800" />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Communication Channel</label>
                    <input type="email" name="email" value={formData.email || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white placeholder-pearl-800" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Direct Contact</label>
                    <input type="tel" name="phone" value={formData.phone || ''} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white placeholder-pearl-800" />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Digital Presence</label>
                  <input type="url" name="website" value={formData.website || ''} onChange={handleInputChange} required placeholder="https://www.example.com" className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white placeholder-pearl-800" />
                </div>

                <div>
                  <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Vision & Mission</label>
                  <textarea rows={4} name="description" value={formData.description || ''} onChange={handleInputChange} className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 placeholder-pearl-800 resize-none leading-relaxed" placeholder="Describe the company's elite status and mission..." />
                </div>

                <div className="pt-8 flex gap-5 justify-end">
                  <button type="button" onClick={() => setShowEditModal(false)} disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-pearl-500 glass hover:text-white transition-all">
                    Dismiss
                  </button>
                  <button type="submit" disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-onyx-900 bg-gold-gradient hover:brightness-110 transition-all shadow-gold flex items-center gap-3">
                    {formLoading ? (
                       <><div className="w-4 h-4 border-2 border-onyx-900/30 border-t-onyx-900 rounded-full animate-spin"></div> Syncing...</>
                    ) : 'Commit Changes'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Add Job Modal */}
      {showJobModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-onyx-950/80 backdrop-blur-md overflow-y-auto">
          <div className="glass rounded-[3rem] w-full max-w-4xl shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-pearl-900/10 overflow-hidden my-auto animate-fade-in-up">
            <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
              <h3 className="text-2xl font-serif font-bold text-white">Announce New Position</h3>
              <button onClick={() => setShowJobModal(false)} className="text-pearl-600 hover:text-white bg-onyx-800 p-2.5 rounded-xl transition-all border border-pearl-900/10">
                <X size={20} />
              </button>
            </div>

            <div className="p-10 max-h-[75vh] overflow-y-auto custom-scrollbar">
              {message && (
                <div className={`p-5 rounded-2xl mb-8 font-bold text-sm uppercase tracking-widest flex items-start gap-4 ${message.includes('successfully') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0" /> : <X size={20} className="shrink-0" />}
                  <p>{message}</p>
                </div>
              )}

              <form onSubmit={handleJobSubmit} className="space-y-12">

                {/* Core Details */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Strategic Details
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Position Title</label>
                      <input type="text" name="title" value={jobFormData.title} onChange={handleJobInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" placeholder="e.g., Lead Architect" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Location Strategy</label>
                      <input type="text" name="location" value={jobFormData.location} onChange={handleJobInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" placeholder="e.g., London / Remote" />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Engagement Model</label>
                      <select name="jobType" value={jobFormData.jobType} onChange={handleJobInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white appearance-none cursor-pointer">
                        <option value="Full-time">Full-time Engagement</option>
                        <option value="Part-time">Part-time Engagement</option>
                        <option value="Internship">Elite Internship</option>
                        <option value="Contract">Strategic Contract</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Experience Protocol</label>
                      <input type="text" name="experience" value={jobFormData.experience} onChange={handleJobInputChange} placeholder="e.g., 5+ Years" required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Compensation Package</label>
                      <input type="text" name="salary" value={jobFormData.salary} onChange={handleJobInputChange} placeholder="Premium Range" required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Closure Date</label>
                      <input type="date" name="applicationDeadline" value={jobFormData.applicationDeadline} onChange={handleJobInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white invert opacity-80" />
                    </div>
                  </div>
                </div>

                {/* Job Intellectual Scope */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Intellectual Scope
                  </h4>

                  <div className="mb-8">
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Executive Summary</label>
                    <textarea rows={4} name="description" value={jobFormData.description} onChange={handleJobInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 placeholder-pearl-800 resize-none leading-relaxed" />
                  </div>

                  <div className="mb-8">
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Strategic Requirements (one per line)</label>
                    <textarea rows={4} name="requirements" value={jobFormData.requirements} onChange={handleJobInputChange} placeholder="Command of architectural patterns&#10;Leadership in cross-functional teams" required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 placeholder-pearl-800 resize-none leading-relaxed" />
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Technical Stack (comma separated)</label>
                    <input type="text" name="skills" value={jobFormData.skills} onChange={handleJobInputChange} placeholder="e.g. AWS, Kubernetes, React" className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                  </div>
                </div>

                {/* Selective Filters */}
                <div className="bg-white/5 p-8 rounded-3xl border border-pearl-900/10">
                  <h4 className="text-sm font-bold text-white mb-8">Selection Protocol</h4>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Minimum Academic Standing</label>
                      <input type="number" step="0.1" min="0" max="10" name="eligibility.minCGPA" value={jobFormData.eligibilityCriteria.minCGPA} onChange={handleJobInputChange} className="w-full px-5 py-4 rounded-2xl bg-onyx-900 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Academic Seniority</label>
                      <select name="eligibility.year" value={jobFormData.eligibilityCriteria.year} onChange={handleJobInputChange} className="w-full px-5 py-4 rounded-2xl bg-onyx-900 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white appearance-none cursor-pointer">
                        <option value={1}>Foundation Year</option>
                        <option value={2}>Sophomore Year</option>
                        <option value={3}>Pre-Final Year</option>
                        <option value={4}>Finalist Year</option>
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-5">Departmental Focus</label>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                      {['Computer Science', 'Information Technology', 'Electronics', 'Mechanical', 'Civil', 'Electrical'].map(dept => (
                        <label key={dept} className={`flex items-center gap-4 p-4 rounded-2xl cursor-pointer border transition-all ${jobFormData.eligibilityCriteria.departments.includes(dept) ? 'bg-gold-500/10 border-gold-500/30 text-gold-500' : 'bg-onyx-900 border-pearl-900/10 text-pearl-600 hover:border-pearl-900/30'}`}>
                          <input type="checkbox" value={dept} checked={jobFormData.eligibilityCriteria.departments.includes(dept)} onChange={handleDepartmentChange} className="hidden" />
                          <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-all ${jobFormData.eligibilityCriteria.departments.includes(dept) ? 'bg-gold-500 border-gold-500' : 'border-pearl-900'}`}>
                            {jobFormData.eligibilityCriteria.departments.includes(dept) && <div className="w-2 h-2 bg-onyx-900 rounded-full"></div>}
                          </div>
                          <span className="text-xs font-bold uppercase tracking-tight">{dept}</span>
                        </label>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="pt-10 flex gap-5 justify-end">
                  <button type="button" onClick={() => setShowJobModal(false)} disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-pearl-500 glass hover:text-white transition-all">
                    Cancel
                  </button>
                  <button type="submit" disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-onyx-900 bg-gold-gradient hover:brightness-110 transition-all shadow-gold flex items-center gap-3">
                    {formLoading ? (
                      <><div className="w-4 h-4 border-2 border-onyx-900/30 border-t-onyx-900 rounded-full animate-spin"></div> Publishing...</>
                    ) : 'Publish Listing'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployerProfile;
